1	"use client";
2	
3	import { Component, useMemo, useSyncExternalStore, type ReactNode } from "react";
4	import dynamic from "next/dynamic";
5	
6	// Loaded on the client only, so echarts never ships in the server render or blocks first paint.
7	// App charts use a trimmed echarts (bar, line, scatter); answer charts may use any type, so they load the full build.
8	export const ReactECharts = dynamic(() => import("./echarts-lean"), { ssr: false });
9	// Pages that import this module eagerly (Plan) start the echarts download before their chart renders.
10	if (typeof window !== "undefined") void import("./echarts-lean");
11	const FullECharts = dynamic(() => import("echarts-for-react"), { ssr: false });
12	
13	function subscribeTheme(onChange: () => void) {
14	  const observer = new MutationObserver(onChange);
15	  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
16	  return () => observer.disconnect();
17	}
18	
19	/** Resolves a color token to a concrete color; tokens are light-dark() pairs, which ECharts cannot parse. */
20	function token(name: string, fallback: string) {
21	  if (typeof document === "undefined") return fallback;
22	  const probe = document.createElement("span");
23	  probe.style.color = `var(${name})`;
24	  document.body.appendChild(probe);
25	  const color = getComputedStyle(probe).color;
26	  probe.remove();
27	  return color || fallback;
28	}
29	
30	// Chart colors follow the app's CSS tokens, including the dark theme.
31	export function useThemeColors() {
32	  const theme = useSyncExternalStore(subscribeTheme, () => document.documentElement.dataset.theme ?? "light", () => "light");
33	  return useMemo(() => {
34	    const fallback = theme === "dark" ? { brand: "#cbf26b", muted: "#a3a39e", border: "#24262a", card: "#16171a", input: "#3987e5", output: "#d95926", out: "#5b5d62" } : { brand: "#4a6400", muted: "#5c5d58", border: "#e2e0d8", card: "#ffffff", input: "#2a78d6", output: "#eb6834", out: "#a9aaa3" };
