1	import { streamText, tool, stepCountIs, type ToolSet, type ToolExecutionOptions } from "ai";
2	import { z } from "zod";
3	import { modelForSettings, SYSTEM_PROMPT } from "@/lib/ai/provider";
4	import { requireWorkspace } from "@/lib/auth";
5	import { requireAiScope, type AiDataScope } from "@/lib/settings";
6	import { calendarDate } from "@/lib/finance/calendar";
7	import { reportedUsage } from "@/lib/ai/usage";
8	import { parseCategoryCommand } from "@/lib/ai/write-intent";
9	import {reviewRequestSchema, resolveReviewRequest} from "@/lib/finance/review-request";
10	import { loadFinancialReviewEvidence } from "@/lib/finance/review-loader";
11	import { startFinancialReview } from "@/lib/finance/start-review";
12	import { categoryPreviewSchema, loadCategoryPreview } from "@/lib/finance/edit-preview";
13	import { cashflow, evaluateForecast, financeToolSchemas, forecastInput, getBalances, listAccounts, listGoals, searchTransactions } from "@/lib/finance/tools";
14	import { investigationSchema } from "@/lib/finance/investigation";
15	import { evaluateInvestigationScenario, investigationDetail, investigationDetailSchema, investigationScenarioSchema, loadInvestigationEntities, runInvestigation } from "@/lib/finance/investigation-reader";
16	import type { ChatStreamEvent } from "@/lib/ai/use-chat-request";
17	import { chatFollowUps, planInput } from "@/lib/ai/follow-ups";
18	import { iouInputSchema, proposeIou, proposeRepayments } from "@/lib/ai/iou-proposals";
19	import { proposeTransaction, transactionInputSchema } from "@/lib/ai/transaction-proposals";
20	import { balanceInputSchema, proposeBalance } from "@/lib/ai/balance-proposals";
21	import { APP_GUIDE } from "@/lib/ai/app-guide";
22	import { MAX_ATTACHMENTS, attachmentNote, attachmentSchema } from "@/lib/ai/chat-attachments";
23	import { agentDecisionSchema, agentFindings, decisionBlock, openAgentProposalIds } from "@/lib/ai/agent-findings";
24	import { readableToolOutput, toolOutputPreview, type EntityNames } from "@/lib/ai/tool-output";
25	
26	/** Chart blocks are rendered for people; the model only needs to know one was shown. */
27	function withoutCharts(content: string) {
28	  return content.replace(/```(?:chart|moneo-chart)\n[\s\S]*?```/g, "[chart]").replace(/```moneo-(?:proposals?|decision)\n[\s\S]*?```/g, "[card shown]");
29	}
30	
31	const inputSchema = z.object({
32	  conversationId: z.uuid(),
33	  requestId: z.uuid(),
34	  message: z.string().trim().min(1).max(4000),
35	  context: z.record(z.string(), z.unknown()).optional(),
36	  attachments: z.array(attachmentSchema).max(MAX_ATTACHMENTS).optional(),
37	}).strict();
38	
39	export async function POST(request: Request) {
40	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
41	  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
42	  const body = await request.json().catch(() => null);
43	  const parsed = inputSchema.safeParse(body);
44	  if (!parsed.success || JSON.stringify(parsed.data.context ?? {}).length > 2000)
45	    return Response.json({ error: "Invalid message" }, { status: 400 });
46	  if (!(process.env.OPENAI_API_KEY || process.env.OPENROUTER_API_KEY)) return Response.json({ error: "AI is not configured" }, { status: 503 });
47	  const { conversationId, requestId, message, context: capturedContext, attachments = [] } = parsed.data;
48	  const { supabase, workspace, settings } = context;
49	  if (attachments.some(file => !file.path.startsWith(`${workspace.id}/`))) return Response.json({ error: "Invalid attachment" }, { status: 400 });
50	  // Model resolution and earlier history do not depend on the claim; start them with the ownership check.
51	  const modelPromise = modelForSettings(settings, "chat");
52	  const historyPromise = Promise.resolve(supabase.from("messages").select("role, content, context, attachments")
53	    .eq("workspace_id", workspace.id).eq("conversation_id", conversationId)
54	    .order("created_at", { ascending: false }).limit(19));
55	  modelPromise.catch(() => {});
56	  historyPromise.catch(() => {});
57	  const existing = await supabase.from("conversations").select("id, deleted_at").eq("workspace_id", workspace.id).eq("id", conversationId).maybeSingle();
58	  if (existing.error) throw existing.error;
59	  if (existing.data?.deleted_at) return Response.json({ error: "Conversation was deleted" }, { status: 404 });
60	  if (!existing.data) {
61	    const { error } = await supabase.from("conversations").insert({ id: conversationId, workspace_id: workspace.id, title: message.slice(0, 80) });
62	    if (error && error.code !== "23505") return Response.json({ error: "Conversation unavailable" }, { status: 403 });
63	  }
64	  const claim = await supabase.rpc("start_chat_request", {
65	    p_request_id: requestId, p_conversation_id: conversationId, p_message: message, p_context: capturedContext ?? {},
66	  });
67	  if (claim.error) return Response.json({ error: claim.error.message }, { status: 400 });
68	  if (!claim.data.started) {
69	    if (claim.data.status === "completed") return Response.json({ conversationId, answer: claim.data.answer });
70	    return Response.json({ error: `Request is ${claim.data.status}`, status: claim.data.status }, { status: 409 });
71	  }
72	  if (request.signal.aborted) {
73	    await supabase.rpc("cancel_chat_request", { p_request_id: requestId });
74	    return Response.json({ status: "canceled" }, { status: 409 });
75	  }
76	  // The claim saved the message; its files are kept beside it for the chat history.
77	  if (attachments.length) {
78	    const saved = await supabase.from("messages").update({ attachments }).eq("workspace_id", workspace.id).eq("conversation_id", conversationId)
79	      .eq("request_id", requestId).eq("role", "user");
80	    if (saved.error) console.error("saving chat attachments failed", saved.error);
81	  }
82	  const streaming = request.headers.get("accept")?.includes("application/x-ndjson") ?? false;
83	  async function complete(emit: (event: ChatStreamEvent) => void): Promise<[unknown, number]> {
84	  try {
85	  const { data: history, error: historyError } = await historyPromise;
86	  if (historyError) throw historyError;
87	  // History was read before the claim saved this message, so append it exactly as the claim stores it.
88	  const submitted = { role: "user", content: message, context: capturedContext ?? {}, attachments: [] };
89	  const textMessages = [...(history ?? []).reverse(), submitted].map(item => ({
90	    role: item.role as "user" | "assistant",
91	    content: item.role === "assistant" ? withoutCharts(item.content)
92	      : (item.context && Object.keys(item.context).length ? `${item.content}\n[UI context at submission: ${JSON.stringify(item.context)}]` : item.content) + attachmentNote(item.attachments),
93	  }));
94	  // Only this message's files are read by the model; earlier ones are named in their text.
95	  const files = await Promise.all(attachments.map(async file => {
96	    const { data, error } = await supabase.storage.from("chat").download(file.path);
97	    if (error || !data) throw new Error(`Could not read ${file.name}`);
98	    return { type: "file" as const, data: new Uint8Array(await data.arrayBuffer()), mediaType: file.type, filename: file.name };
99	  }));
100	  const last = textMessages.pop()!;
101	  const modelMessages = [...textMessages, files.length ? { role: "user" as const, content: [{ type: "text" as const, text: last.content }, ...files] } : last];
102	  const categoryCommand = parseCategoryCommand(message);
103	  const canChangeCategory = categoryCommand !== null && settings.ai_data_scopes.includes("transactions");
104	  const canInvestigate = settings.ai_data_scopes.includes("accounts") && settings.ai_data_scopes.includes("transactions");
105	  // These checks govern new tool results, not evidence already sent to the provider.
106	  const readScopes = new Set<AiDataScope>();
107	  async function aiEvidence<T>(scopes: AiDataScope[], read: (latest: typeof context) => Promise<T>, includePlanning = false, includeImports = false): Promise<T> {
108	    const latest = await requireWorkspace();
109	    if (latest.workspace.id !== workspace.id) throw new Error("Workspace changed");
110	    requireAiScope(latest.settings, ...scopes);
111	    const usedScopes = [...scopes,
112	      ...(includePlanning && latest.settings.ai_data_scopes.includes("planning") ? ["planning" as const] : []),
113	      ...(includeImports && latest.settings.ai_data_scopes.includes("imports") ? ["imports" as const] : [])];
114	    const result = await read(latest);
115	    const current = await requireWorkspace();
116	    if (current.workspace.id !== workspace.id) throw new Error("Workspace changed");
117	    if (request.signal.aborted) throw new Error("Request canceled");
118	    requireAiScope(current.settings, ...usedScopes);
119	    for (const scope of usedScopes) readScopes.add(scope);
120	    return result;
121	  }
122	  // Owned names label ids in tool output, so the model never needs a separate lookup step.
123	  let entityNames: Promise<EntityNames> | undefined;
124	  function namesFor(latest: typeof context): Promise<EntityNames> {
125	    return entityNames ??= Promise.all((["account", "category", "merchant"] as const).map(async dimension => {
126	      if (!latest.settings.ai_data_scopes.includes(dimension === "account" ? "accounts" : "transactions")) return [dimension, new Map<string, string>()] as const;
127	      const table = dimension === "account" ? "accounts" : dimension === "category" ? "categories" : "merchants";
128	      const { data, error } = await latest.supabase.from(table).select("id, name").eq("workspace_id", workspace.id).limit(5000);
129	      if (error) throw error;
130	      return [dimension, new Map((data ?? []).map((row: { id: string; name: string }) => [row.id, row.name]))] as const;
131	    })).then(entries => Object.fromEntries(entries));
132	  }
133	  const toolCalls: { name: string; input: unknown; output: string }[] = [];
134	  function retainTools<T extends ToolSet>(tools: T): T {
135	    return Object.fromEntries(Object.entries(tools).map(([name, definition]) => [name, { ...definition,
136	      execute: async (input: unknown, options: ToolExecutionOptions<unknown>) => {
137	        const execute = definition.execute as (input: unknown, options: ToolExecutionOptions<unknown>) => Promise<unknown>;
138	        emit({ type: "tool", id: options?.toolCallId, name, state: "running", input });
139	        let output: unknown;
140	        try { output = await execute(input, options); }
141	        catch (cause) { emit({ type: "tool", id: options?.toolCallId, name, state: "failed" }); throw cause; }
142	        const latest = await requireWorkspace();
143	        if (latest.workspace.id !== workspace.id || request.signal.aborted) throw new Error("Request canceled or workspace changed");
144	        // Every scope read so far must still be allowed before more data reaches the model.
145	        requireAiScope(latest.settings, ...readScopes);
146	        const readable = readableToolOutput(output, await namesFor(latest).catch(() => ({})));
147	        const preview = toolOutputPreview(readable);
148	        toolCalls.push({ name, input, output: preview });
149	        emit({ type: "tool", id: options?.toolCallId, name, state: "done", output: preview });
150	        return readable;
151	      },
152	    }])) as T;
153	  }
154	    const model = await modelPromise;
155	    // The visible plan is not financial evidence; it only tells the user what the model will check.
156	    let modelFollowUps: string[] = [];
157	    // Loan cards are drawn by the app beside the answer, so the model cannot misquote or skip them.
158	    const proposalCards: string[] = [];
159	    // Cards shown earlier in this chat; a corrected loan replaces its still-open card.
160	    const earlierCards = (history ?? []).flatMap(item => item.role === "assistant" ? [...item.content.matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []) : []);
161	    // Agent-team decisions are confirmed on a card too; the model only names the ids.
162	    const decisionCards: string[] = [];
163	    const planTool = { plan_investigation: tool({ description: "Optional: show the user 2-5 short steps you will take for a multi-part question, and up to 3 follow-up questions they might ask next. Returns nothing.",
164	      inputSchema: planInput, execute: async input => { emit({ type: "plan", steps: input.steps }); toolCalls.push({ name: "plan_investigation", input, output: "" }); modelFollowUps = input.followUps ?? []; return { shown: true }; } }),
165	      iou_propose: tool({ description: "The user says they lent or gave money to a person, or borrowed or received money from one. Shows them a card to accept or dismiss; nothing is saved until they accept. Use the user's exact amount, person and currency.",
166	        inputSchema: iouInputSchema, execute: async input => {
167	          const created = await proposeIou(await requireWorkspace(), input, [...earlierCards, ...proposalCards]);
168	          proposalCards.push(created.proposalId);
169	          return { proposed: created.title, note: `A card with Add and Dismiss is shown to the user below your answer.${created.replaced ? " It replaces the earlier card for this loan, which was dismissed." : ""} Say it is waiting for their approval; do not repeat the details.` };
170	        } }),
171	      transaction_propose: tool({ description: "The user says they spent, paid, bought, earned or received money (or an attached receipt or invoice shows it). Shows a card to add it to their transactions; nothing is saved until they accept. Call once per separate payment, with the exact amount, currency and date from the user or document.",
172	        inputSchema: transactionInputSchema, execute: async input => {
173	          const created = await proposeTransaction(await requireWorkspace(), input);
174	          proposalCards.push(created.proposalId);
175	          return { proposed: created.title, note: "A card with an account picker, Add and Dismiss is shown below your answer. Say it is waiting for their approval; do not repeat the details." };
176	        } }),
177	      balance_propose: tool({ description: "The user states what an account holds now or held on a date (e.g. 'I have 115 euros in cash', 'my Revolut shows 1,250'). Shows a card to save it as that account's dated balance; nothing changes until they accept. Use the exact amount and currency the user gave.",
178	        inputSchema: balanceInputSchema, execute: async input => {
179	          const created = await proposeBalance(await requireWorkspace(), input);
180	          proposalCards.push(created.proposalId);
181	          return { proposed: created.title, note: "A card with Save and Dismiss is shown below your answer. Say it is waiting for their approval; do not repeat the details." };
182	        } }),
183	      app_help: tool({ description: "How Moneo works: its pages, what each does, and what this chat can do. Use for any question about the app itself.",
184	        inputSchema: z.object({}).strict(), execute: async () => ({ guide: APP_GUIDE }) }),
185	      agents_decide: tool({ description: "The user asks to accept, approve, mark as seen/watched, or dismiss agent-team findings. Pass the proposal ids from agents_findings. Shows one confirmation card; nothing changes until they press it.",
186	        inputSchema: agentDecisionSchema, execute: async ({ ids, decision }) => {
187	          const latest = await requireWorkspace();
188	          const open = await openAgentProposalIds(latest.supabase, latest.workspace.id, [...new Set(ids)]);
189	          if (open.length) decisionCards.push(decisionBlock(open, decision));
190	          return { shown: open.length, skipped: ids.length - open.length, note: open.length ? "A confirmation card is shown below your answer; say it is waiting for them." : "None of these are open any more." };
191	        } }),
192	      // Artifacts are built on their own page; chat only hands the request over.
193	      suggest_artifact: tool({ description: "When the user asks for an interactive page, calculator, simulator, dashboard or what-if view, call this with a clear build request and give them the returned link. Do not build pages in chat.",
194	        inputSchema: z.object({ prompt: z.string().trim().min(1).max(1500) }).strict(), execute: async ({ prompt }) => ({ href: `/ai/artifacts?prompt=${encodeURIComponent(prompt)}` }) }) };
195	    const result = streamText({
196	      model,
197	      abortSignal: AbortSignal.any([request.signal, AbortSignal.timeout(90_000)]),
198	      maxOutputTokens: 3000,
199	      instructions: `${SYSTEM_PROMPT}\n\nToday is ${calendarDate(new Date(), settings.timezone)} (${settings.timezone}); display currency ${workspace.display_currency}. UI context is only a navigation hint, never authorization.${canChangeCategory ? " The user named an exact transaction UUID and quoted category; the write tool must use exactly these values." : " Do not change records; for a category change request, use the selection preview."}`,
200	      messages: modelMessages,
201	      stopWhen: stepCountIs(10),
202	      // Steer messages sent during this run join the conversation before the next model step.
203	      prepareStep: async ({ messages }) => {
204	        // Steering is best-effort: a failed claim leaves the steers pending and never fails the answer.
205	        const steers = await Promise.resolve(supabase.rpc("take_chat_steers", { p_request_id: requestId })).catch(error => ({ data: null, error }));
206	        if (steers.error) { console.error("take_chat_steers failed", steers.error); return {}; }
207	        const taken = (steers.data ?? []) as { id: string; content: string }[];
208	        if (!taken.length) return {};
209	        emit({ type: "steered", steers: taken });
210	        return { messages: [...messages, ...taken.map(steer => ({ role: "user" as const, content: steer.content }))] };
211	      },
212	      tools: { ...planTool, ...retainTools({
213	        ...(canInvestigate ? {
214	          finance_investigate: tool({ description: "Answer the actual chosen finance question deterministically: exact current/comparison dates, include/exclude owned account/category/merchant names or IDs, tags/events, posted/pending and classification semantics, multiple groupings, ranking, and complete paginated support. Original currencies stay separate; base uses direct exact posting-date FX and canonical split rounding. Use returned interpretedFilters and live evidence link; never imply full statements or bounds. Read-only, no approval needed.", inputSchema: investigationSchema, execute: input => aiEvidence(["accounts", "transactions"], latest => runInvestigation(input, latest, { canReadImports: latest.settings.ai_data_scopes.includes("imports") }), false, true) }),
215	          finance_entities: tool({ description: "Optional: list owned account, category and merchant names with ids, tags and events. Other tools already accept names and label ids with names.", inputSchema: z.object({}).strict(), execute: () => aiEvidence(["accounts", "transactions"], latest => loadInvestigationEntities(latest)) }),
216	          finance_detail: tool({ description: "Read an owned canonical transaction with its effective split/fee components, or a recurring series with complete paginated source transactions. Classification warnings remain explicit.", inputSchema: investigationDetailSchema, execute: input => aiEvidence(input.kind === "recurring" ? ["accounts", "transactions", "planning"] : ["accounts", "transactions"], latest => investigationDetail(input, latest, { canReadImports: latest.settings.ai_data_scopes.includes("imports") }), false, true) }),
217	          finance_scenario: tool({ description: "Compare the same investigation against at most 100 hypothetical effective-record amount/date/category overrides. Read-only; canonical ledger, sources, balances and recurrence remain unchanged. Use exact minor-unit strings and owned effective IDs.", inputSchema: investigationScenarioSchema, execute: input => aiEvidence(["accounts", "transactions"], latest => evaluateInvestigationScenario(input, latest, { canReadImports: latest.settings.ai_data_scopes.includes("imports") }), false, true) }),
218	        } : {}),
219	        ...(settings.ai_data_scopes.includes("transactions") ? { agents_findings: tool({ description: "Read what the agent team found in its recent runs: open proposals (categorizations, recurring bills, budgets, anomaly findings) with ids, plus each run's briefing and page link. Set includeDecided to also see accepted and dismissed ones.",
220	          inputSchema: z.object({ includeDecided: z.boolean().optional() }).strict(), execute: ({ includeDecided }) => aiEvidence(["transactions"], latest => agentFindings(latest.supabase, workspace.id, { includeDecided })) }) } : {}),
221	        ...(settings.ai_data_scopes.includes("imports") ? { imports_status: tool({
222	          description: "Read recorded import workflow status and row counts. Completed means processing finished, not that all financial classifications or current balances are complete. Use this to answer whether imports are still running; do not infer status from balance freshness or filenames.",
223	          inputSchema: z.object({}).strict(), execute: () => aiEvidence(["imports"], async latest => {
224	            const { data, error } = await latest.supabase.from("imports")
225	              .select("id, filename, status, total_rows, new_rows, matched_rows, review_rows, classification_review_rows, rejected_rows, error")
226	              .eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(30);
227	            if (error) throw error;
228	            return { imports: data ?? [] };
229	          }),
230	        }) } : {}),
231	        ...(settings.ai_data_scopes.includes("transactions") ? { transactions_previewCategory: tool({ description: "Read-only impact preview for exact selected transaction UUIDs and an existing category UUID. Returns a link where the user reviews current entries and explicitly confirms an audited bulk change. Never changes any transaction.", inputSchema: categoryPreviewSchema, execute: ({ transactionIds, categoryId }) => aiEvidence(["transactions"], latest =>
232	          loadCategoryPreview(latest.supabase, workspace.id, transactionIds, categoryId)) }) } : {}),
233	        ...(canInvestigate ? { reviews_investigate: tool({ description: "Investigate the selected query or an explicitly dated default review, with exact spending changes, account evidence, classification limitations and permitted planning evidence. Read-only.", inputSchema: z.object({ query: investigationSchema.optional() }).strict(), execute: ({ query } = {}) => aiEvidence(["accounts", "transactions"], latest =>
234	          loadFinancialReviewEvidence(latest.supabase, latest.workspace, latest.settings, query), true, true) }) } : {}),
235	        ...(canInvestigate ? { reviews_start: tool({ description: "Investigate the current user's finance question through a bounded, durable, cancelable review. Preserve their chosen dates, entities and focus in query/focus; the application binds the exact question and visible navigation context. Use ordinary finance queries for quick answers, and this tool when follow-up evidence gathering or a saved report is useful. Do not start when the user declines investigation or only asks what a review does. Repeated calls reuse one job; no canonical financial changes.", inputSchema: reviewRequestSchema.omit({question: true, version: true, context: true, allowedScopes: true}), execute: (input = {includePlanning: false, output: "answer", budget: {maxQueries: 6, maxSupportRecords: 60, maxOutputTokens: 4000, maxDurationMs: 90000}}) => aiEvidence(["accounts", "transactions"], async latest => {
