244	        ...(settings.ai_data_scopes.includes("transactions") ? { analytics_cashflow: tool({ description: "Exact accepted posted income/spending with source coverage. Choose view base for direct exact posting-date FX and per-canonical-posting half-away rounding, or original for separate currency subtotals. Omitted view preserves single-currency accounting. Conversion completeness does not prove statement completeness; partial totals are not bounds. Missing rates return incomplete evidence, never guessed money.", inputSchema: financeToolSchemas.periodInput, execute: input => aiEvidence(["transactions"], latest => cashflow(input, latest, latest.settings.ai_data_scopes.includes("imports")), false, true) }),
245	        transactions_search: tool({ description: "Find transactions, newest first. Filter by description text, posted date range (from/to), absolute amount range in minor units, and limit (default 20, max 50).", inputSchema: financeToolSchemas.searchInput, execute: input => aiEvidence(["transactions"], latest => searchTransactions(input, latest)) }) } : {}),
246	        ...(canInvestigate ? { iou_findRepayments: tool({ description: "Check recent bank transactions for repayments of money the user lent to or borrowed from people, and show each as a card to accept or dismiss. Nothing changes until they accept.", inputSchema: z.object({}).strict(),
247	          execute: () => aiEvidence(["accounts", "transactions"], async latest => {
248	            const found = await proposeRepayments(latest);
249	            proposalCards.push(...found.map(item => item.id as string));
250	            return { found: found.map(item => item.title), note: found.length ? "Cards are shown to the user below your answer." : "No new repayments found." };
251	          }) }) } : {}),
252	        ...(settings.ai_data_scopes.includes("planning") ? { goals_list: tool({ description: "List the user's goals", inputSchema: z.object({}), execute: () => aiEvidence(["planning"], latest => listGoals(latest)) }) } : {}),
253	        ...(settings.ai_data_scopes.includes("planning") && settings.ai_data_scopes.includes("accounts") && settings.ai_data_scopes.includes("transactions") ? { forecast_evaluate: tool({ description: "Deterministic account headroom and dated funding shortfalls with source coverage. Choose accountId for available to spend; aggregate cash requires explicit funding. Cases are assumptions, not probabilities", inputSchema: forecastInput, execute: input => aiEvidence(["accounts", "transactions", "planning"], latest => evaluateForecast(input, latest), false, true) }) } : {}),
254	        ...(canChangeCategory ? {
255	          transactions_setCategory: tool({
256	            description: "Change only the category of a specific transaction, only when the current user explicitly asked for this change. Search first if its ID is unknown. The correction is audited and can be undone from the returned transaction link.",
257	            inputSchema: z.object({ transactionId: z.uuid(), category: z.string().trim().min(1).max(100) }).strict(),
258	            execute: async ({ transactionId, category }) => {
259	              if (!categoryCommand || transactionId !== categoryCommand.transactionId || category !== categoryCommand.category)
260	                throw new Error("Action must match the exact transaction and category selected by the user");
261	              const { data, error } = await supabase.rpc("chat_set_category", {
262	                p_request_id: requestId, p_transaction_id: transactionId, p_category: category,
263	              });
264	              if (error) throw error;
265	              return data;
266	            },
267	          }),
268	        } : {}),
269	      }) },
270	    });
271	    // The answer is all text the model wrote, across steps, exactly as streamed to the user.
272	    let text = "", stepBreak = false;
273	    for await (const part of result.fullStream) {
274	      if (part.type === "text-delta" && part.text) {
275	        const delta = stepBreak && text.trim() ? `\n\n${part.text}` : part.text;
276	        stepBreak = false; text += delta;
277	        emit({ type: "delta", text: delta });
278	      } else if (part.type === "finish-step") stepBreak = true;
279	      else if (part.type === "error") throw part.error instanceof Error ? part.error : new Error("AI request failed");
280	    }
281	    const [usage, steps] = await Promise.all([result.usage, result.steps]);
282	    if (!text.trim()) throw new Error("The model returned no answer");
283	    // Several cards from one answer are grouped so they can also be added all at once.
284	    const cards = [...new Set(proposalCards)];
285	    const cardBlocks = cards.length > 1 ? ["```moneo-proposals\n" + JSON.stringify(cards) + "\n```"] : cards.map(id => "```moneo-proposal\n" + id + "\n```");
286	    const answer = [text.trim(), ...cardBlocks, ...new Set(decisionCards)].join("\n\n");
287	    const current = await requireWorkspace();
288	    if (current.workspace.id !== workspace.id) throw new Error("Workspace changed");
289	    if (request.signal.aborted) throw new Error("Request canceled");
