294	    emit({ type: "answer", conversationId, answer, toolsUsed, followUps });
295	    const finished = await supabase.rpc("finish_chat_request", { p_request_id: requestId, p_status: "completed", p_content: answer,
296	      p_usage: reportedUsage(model.modelId, usage), p_tool_calls: toolCalls });
297	    if (finished.error) throw finished.error;
298	    if (finished.data !== "completed") return [{ status: finished.data, error: `Request is ${finished.data}` }, 409];
