300	  } catch (error) {
301	    const failure = error instanceof Error ? error.message : "AI request failed";
302	    if (request.signal.aborted) await supabase.rpc("cancel_chat_request", { p_request_id: requestId });
303	    else await supabase.rpc("finish_chat_request", { p_request_id: requestId, p_status: "failed", p_content: failure.slice(0, 500) });
304	    return [{ error: error instanceof Error ? error.message : "AI request failed" }, 502];
305	  }
306	  }
307	  if (!streaming) { const [body, status] = await complete(() => {}); return Response.json(body, { status }); }
308	  // Opt-in NDJSON: tool progress and the verified answer arrive before publication finishes.
309	  const encoder = new TextEncoder();
310	  return new Response(new ReadableStream({ start(controller) {
311	    const write = (event: ChatStreamEvent) => { try { controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`)); } catch { /* the reader went away; work continues */ } };
312	    write({ type: "started" });
313	    void complete(write).then(([body, status]) => { write({ type: "result", status, body }); try { controller.close(); } catch { /* already closed */ } });
314	  } }), { headers: { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store" } });
315	}
316	
317	
318	export async function PATCH(request: Request) {
