320	  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
321	  const parsed = z.object({ requestId: z.uuid() }).strict().safeParse(await request.json().catch(() => null));
322	  if (!parsed.success) return Response.json({ error: "Invalid cancellation" }, { status: 400 });
