318	export async function PATCH(request: Request) {
319	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
320	  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
321	  const parsed = z.object({ requestId: z.uuid() }).strict().safeParse(await request.json().catch(() => null));
322	  if (!parsed.success) return Response.json({ error: "Invalid cancellation" }, { status: 400 });
323	  const result = await context.supabase.rpc("cancel_chat_request", { p_request_id: parsed.data.requestId });
324	  if (result.error) return Response.json({ error: result.error.message }, { status: result.error.code === "P0002" ? 404 : 400 });
325	  return Response.json({ status: result.data });
326	}
